import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello,Entrar,enCamino} from './kit';
// VARIADO 29-nov 09:00 · Tu brazo va a subir solo (efecto Kohnstamm). 2.5D: volumen (Vol), 3 capas con parallax, giro leve, sombra en el suelo.
export const SUBS={arriba:1340,size:84,acento:'#E7FF00'};
const L='#E7FF00';
const A=[0,6,17,32,37,49,54,67,79,92,105,115,124,137].map(T);
const P=(w:string,n=1)=>en(w,n)-.2; // la imagen entra 0,2 s antes de la palabra
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const qo=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.out(Easing.cubic)});
const ql=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],clamp);
const pop=(s:number,t:number)=>s<t?0:Math.max(0,1-Math.exp(-(s-t)*9)*Math.cos((s-t)*18));
const RAD=Math.PI/180;
type C3=[string,string,string];
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
// Cápsula cerrada de (x1,y1) a (x2,y2) con grosor w: dedos, brazos y piernas con volumen (nunca trazos sueltos).
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const PIEL:C3=['#ffe6d2','#f2b08a','#b0603e'],PIEL2:C3=['#e0a878','#a8693c','#5a3016'];
const PELO:C3=['#b88560','#6a432a','#241208'],PELO2:C3=['#6a6a80','#25252f','#07070c'];
const MENTA:C3=['#c4ffec','#2EE6A6','#08966a'],NARAN:C3=['#ffd0a0','#ff8a1f','#a04200'];
const NEGRO:C3=['#7a7e98','#272a36','#07080c'],ZAPA:C3=['#ffffff','#e6edf6','#8a99b0'];
const ROJO:C3=['#ff9a8a','#d63a3a','#6a0a14'],ROSA:C3=['#ffe0e8','#f09ab0','#8a2c4c'],HUESO:C3=['#fffaf0','#efe2c4','#b8a47a'],LIB:C3=['#ff8a7a','#d41f3a','#6a0618'];
// Volumen: color medio, sombra suave abajo-derecha, luz suave arriba-izquierda y borde fino.
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
// Volumen barato (sin desenfoque) para dedos, uñas y piezas chicas.
const VolS:React.FC<{id:string;d:string;c:C3;o?:number}>=({id,d,c,o=3})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={o*2.6} opacity={.8} transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={o*1.8} opacity={.85} transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={c[2]} strokeWidth={1.6} opacity={.5}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const FLOOR=1196;
const Defs:React.FC=()=><defs>
 <filter id='b3' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='3'/></filter>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.5'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <radialGradient id='irisG' cx='.4' cy='.35'><stop stopColor='#dba468'/><stop offset='.6' stopColor='#7a4a20'/><stop offset='1' stopColor='#2a160c'/></radialGradient>
 <radialGradient id='bolaG' cx='.35' cy='.3'><stop stopColor='#fff2c8'/><stop offset='.45' stopColor='#FF8A1F'/><stop offset='1' stopColor='#b03a00'/></radialGradient>
 <linearGradient id='madera' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#f6c993'/><stop offset='.35' stopColor='#d8975a'/><stop offset='1' stopColor='#6e3a1a'/></linearGradient>
 <linearGradient id='parL' x1='0' y1='0' x2='1' y2='0'><stop stopColor='#000' stopOpacity='.5'/><stop offset='.8' stopColor='#000' stopOpacity='.12'/><stop offset='.93' stopColor='#ffb060' stopOpacity='.0'/><stop offset='1' stopColor='#ffd9a0' stopOpacity='.55'/></linearGradient>
 <linearGradient id='parR' x1='1' y1='0' x2='0' y2='0'><stop stopColor='#000' stopOpacity='.5'/><stop offset='.8' stopColor='#000' stopOpacity='.12'/><stop offset='.93' stopColor='#ffb060' stopOpacity='.0'/><stop offset='1' stopColor='#ffd9a0' stopOpacity='.55'/></linearGradient>
 <radialGradient id='luzF' cx='.62' cy='.35' r='.6'><stop stopColor='#ffcf8a' stopOpacity='.65'/><stop offset='1' stopColor='#000' stopOpacity='.45'/></radialGradient>
 <linearGradient id='negroInt' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#2a0610'/><stop offset='1' stopColor='#080004'/></linearGradient>
 <pattern id='ladr' width='160' height='84' patternUnits='userSpaceOnUse'>
  <rect width='160' height='84' fill='#0a2aa8'/>
  {[[4,3],[84,3],[-36,45],[44,45],[124,45]].map(([x,y],j)=><g key={j}><rect x={x} y={y} width={72} height={36} rx={5} fill='#1f4bff'/><rect x={x} y={y} width={72} height={6} rx={3} fill='#7ea0ff' opacity={.7}/><rect x={x} y={y+30} width={72} height={6} rx={3} fill='#0b2fb8' opacity={.8}/></g>)}
 </pattern>
</defs>;
const BG:[string,string][]=[['#ff9a45','#0a1c7a'],['#ff9a45','#0a1c7a'],['#ff9a45','#0a1c7a'],['#ff9a45','#0a1c7a'],['#ff9a45','#0a1c7a'],['#ff9a45','#0a1c7a'],['#33d4ff','#04205e'],['#ff6a2a','#14000a'],['#ff6a2a','#14000a'],['#e0307a','#14000a'],['#ff6a2a','#14000a'],['#ff9a45','#0a1c7a'],['#ff9a45','#0a1c7a'],['#ff7a8a','#10206a']];
const bgOf=(i:number,s:number):[string,string]=>{if(i===7)return s<en('cerebro')?BG[5]:BG[7];if(i===10)return s<en('brazo',4)-.2?BG[10]:BG[11];return BG[i];};

// ============ LUCÍA (cuerpo 2D articulado con volumen) ============
type Cara={ojo?:number;ceja?:number;furia?:number;boca?:'calm'|'smile'|'o'|'press'|'frown'|'laugh';gx?:number;gy?:number;sudor?:number};
const Mano:React.FC<{id:string;c:C3;rojo?:number;curl?:number;s:number}>=({id,c,rojo=0,curl=.3,s})=>{
 const F:[number,number,number][]=[[-22,60,-4],[-7.5,70,-1.5],[7.5,66,1.5],[22,52,4]];
 return <g>
  {F.map(([x,l,dx],j)=>{const ex=x+dx*(1+curl)+Math.sin(s*1.7+j)*curl*3,ey=78+l*(1-.14*curl);
   return <g key={j}><VolS id={id+'f'+j} d={caps(x,78,ex,ey,15)} c={c} o={3}/>
    <path d={`M${ex-5} ${ey-5}Q${ex} ${ey-17} ${ex+5} ${ey-5}Q${ex} ${ey+2} ${ex-5} ${ey-5}Z`} fill='#ffe3dc' stroke={c[2]} strokeWidth={1.4} opacity={.95}/>
    <ellipse cx={ex-1} cy={ey-10} rx={1.8} ry={3} fill='#fff' opacity={.8}/></g>;})}
  <VolS id={id+'th'} d={caps(30,18,52+curl*4,58,17)} c={c} o={3}/>
  <path d={`M${47+curl*4} ${56}Q${52+curl*4} 47 ${57+curl*4} ${56}Q${52+curl*4} 63 ${47+curl*4} 56Z`} fill='#ffe3dc' stroke={c[2]} strokeWidth={1.4}/>
  <Vol id={id+'p'} d='M-23 -10C-33 20 -35 50 -31 82C-12 94 12 94 31 82C35 50 33 20 23 -10C12 -4 -12 -4 -23 -10Z' c={c} sw={26} o={7}/>
  {[0,1,2].map(j=><path key={j} d={`M${-12+j*12} 8Q${-14+j*13} 40 ${-16+j*14} 68`} stroke={c[2]} strokeWidth={2.4} fill='none' opacity={.3}/>)}
  {[-22,-7.5,7.5,22].map((x,j)=><g key={j}><ellipse cx={x} cy={77} rx={9} ry={7} fill={c[0]} opacity={.7}/><ellipse cx={x} cy={77} rx={9} ry={7} fill='#ff1f2a' opacity={rojo*.75} filter='url(#b3)'/></g>)}
  <ellipse cx={-6} cy={26} rx={8} ry={20} transform='rotate(8 -6 26)' fill='#fff' opacity={.28} filter='url(#b3)'/>
 </g>;};
// Brazo continuo: un solo contorno de piel que se afina del hombro a la muñeca (codo suave), con luz y sombra laterales.
const sm=(u:number)=>u*u*(3-2*u);
const armGeo=(S:[number,number],E:[number,number],W:[number,number],w0=36,w1=26,w2=19)=>{
 const cx=2*E[0]-(S[0]+W[0])/2,cy=2*E[1]-(S[1]+W[1])/2,N=40;const Lf:[number,number][]=[],Rt:[number,number][]=[],Ce:[number,number][]=[];
 for(let i=0;i<=N;i++){const tt=i/N,u=1-tt;const x=u*u*S[0]+2*u*tt*cx+tt*tt*W[0],y=u*u*S[1]+2*u*tt*cy+tt*tt*W[1];
  const dx=2*u*(cx-S[0])+2*tt*(W[0]-cx),dy=2*u*(cy-S[1])+2*tt*(W[1]-cy),ln=Math.hypot(dx,dy)||1,nx=-dy/ln,ny=dx/ln;
  const w=(tt<.5?w0+(w1-w0)*sm(tt/.5):w1+(w2-w1)*sm((tt-.5)/.5))+3.5*Math.sin(Math.PI*Math.min(1,tt*1.25));
  Lf.push([x+nx*w,y+ny*w]);Rt.push([x-nx*w,y-ny*w]);Ce.push([x,y]);}
 const P=(a:[number,number][])=>a.map(p=>p[0].toFixed(1)+' '+p[1].toFixed(1)).join('L');
 const d='M'+P(Lf)+'L'+P(Rt.slice().reverse())+`A${w0} ${w0} 0 0 0 ${Lf[0][0].toFixed(1)} ${Lf[0][1].toFixed(1)}Z`;
 return {d,Lf:'M'+P(Lf),Rt:'M'+P(Rt),Ce:'M'+P(Ce)};};
const Miembro:React.FC<{id:string;S:[number,number];E:[number,number];W:[number,number];c:C3;swap?:boolean;w0?:number;w1?:number;w2?:number}>=({id,S,E,W,c,swap=false,w0,w1,w2})=>{
 const g=armGeo(S,E,W,w0,w1,w2),sh=swap?g.Lf:g.Rt,li=swap?g.Rt:g.Lf;
 return <g>
  <defs><clipPath id={id}><path d={g.d}/></clipPath></defs>
  <path d={g.d} fill={c[1]}/>
  <g clipPath={`url(#${id})`}>
   <path d={sh} fill='none' stroke={c[2]} strokeWidth={40} filter='url(#b18)' opacity={.9}/>
   <path d={li} fill='none' stroke={c[0]} strokeWidth={30} filter='url(#b18)' opacity={.9} transform='translate(0 -2)'/>
   <path d={g.Ce} fill='none' stroke={c[0]} strokeWidth={9} filter='url(#b6)' opacity={.35} transform={`translate(${swap?10:-10} 0)`}/>
  </g>
  <path d={li} fill='none' stroke={c[2]} strokeWidth={2.5} opacity={.45}/><path d={sh} fill='none' stroke={c[2]} strokeWidth={2.5} opacity={.55}/>
 </g>;};
const Brazo:React.FC<{id:string;th:number;el?:number;lado?:1|-1;c:C3;esf?:number;rojo?:number;s:number;curl?:number;inv?:boolean}>=({id,th,el=0,lado=1,c,esf=0,rojo=0,s,curl=.3,inv=false})=>{
 const tr=lado===1?`translate(-126 -300) rotate(${th})`:`translate(126 -300) scale(-1 1) rotate(${th})`;
 const er=el*RAD,W:[number,number]=[-170*Math.sin(er),190+170*Math.cos(er)];
 return <g transform={tr}>
  <g transform={`translate(${W[0]} ${W[1]}) rotate(${el}) translate(0 -4)`}><Mano id={id+'m'} c={c} rojo={rojo} curl={curl} s={s}/></g>
  <Miembro id={id+'arm'} S={[0,-26]} E={[0,190]} W={[W[0],W[1]+6]} c={c} swap={(lado===-1)!==inv}/>
  <ellipse cx={W[0]} cy={W[1]+4} rx={21} ry={10} fill={c[1]} filter='url(#b6)' opacity={.9}/>
  {esf>0&&<g opacity={esf}><ellipse cx={-6} cy={14} rx={30} ry={52} fill='#ff3a1a' opacity={.34} filter='url(#b18)'/><Brillo2 x={-16} y={-16} rx={13} ry={32} r={12} o={.75}/>
   <path d='M-30 8Q-12 30 -22 70M2 -6Q16 30 8 74' stroke='#7a0a14' strokeWidth={4} fill='none' opacity={.5}/>
   <path d='M-70 -26L-100 -42M-78 6L-112 10M-68 40L-96 60' stroke={L} strokeWidth={7} strokeLinecap='round'/></g>}
 </g>;};
const Cabeza:React.FC<{id:string;s:number;c:C3;pelo:C3;cara:Cara;amiga?:boolean}>=({id,s,c,pelo,cara,amiga=false})=>{
 const {ojo=1,ceja=0,furia=0,boca='calm',gx=0,gy=0,sudor=0}=cara;
 const par=s%3.3<.11?.1:1,op=Math.max(.05,ojo*par),sw=Math.sin(s*1.8)*5;
 const Ojo=(k:number)=><g key={k} transform={`translate(${k*36} -8)`}>
  <defs><clipPath id={id+'oc'+k}><path d={`M-23 0Q0 ${-26*op} 23 0Q0 ${19*op} -23 0Z`}/></clipPath></defs>
  <path d={`M-23 0Q0 ${-26*op} 23 0Q0 ${19*op} -23 0Z`} fill='#fff'/>
  <g clipPath={`url(#${id}oc${k})`}><circle cx={gx} cy={gy} r={op>1?13:12} fill='url(#irisG)'/><circle cx={gx} cy={gy} r={5.5} fill='#050302'/><circle cx={gx+4.5} cy={gy-5} r={3.8} fill='#fff'/><circle cx={gx-4} cy={gy+4} r={1.8} fill='#fff' opacity={.7}/>
   <path d={`M-24 0Q0 ${-27*op} 24 0L24 -40L-24 -40Z`} fill={c[1]} opacity={op<.4?1:0}/></g>
  <path d={`M-25 0Q0 ${-30*op} 25 0`} stroke='#2a160c' strokeWidth={5.5} fill='none' strokeLinecap='round'/>
  <path d={`M${k*22} -2l${k*8} -5M${k*20} 1l${k*9} -1`} stroke='#2a160c' strokeWidth={3} strokeLinecap='round'/>
  <path d={`M-22 3Q0 ${20*op} 22 3`} stroke={c[2]} strokeWidth={2} fill='none' opacity={.4}/>
  <path d={`M${-k*40} ${-40-ceja*14}Q${-k*14} ${-52-ceja*14} ${k*14} ${-44-ceja*14+furia*14}`} transform={`translate(${-k*36} 8) scale(${-k} 1)`} stroke={pelo[2]} strokeWidth={0} fill='none'/>
 </g>;
 const Ceja=(k:number)=><path key={k} d={`M${k*58} ${-38-ceja*16}Q${k*34} ${-56-ceja*16+furia*6} ${k*12} ${-44-ceja*16+furia*18}`} stroke={pelo[2]} strokeWidth={11} fill='none' strokeLinecap='round' opacity={.95}/>;
 return <g>
  {!amiga?<g transform={`rotate(${sw} 56 -92)`}>
    <Vol id={id+'pt'} d='M52 -100C142 -130 190 -52 166 54C154 108 120 152 82 172C104 102 102 32 58 -34Z' c={pelo} sw={30} o={8}/>
    <ellipse cx={58} cy={-88} rx={22} ry={14} fill='#2EE6A6' stroke='#08966a' strokeWidth={3}/></g>
   :[-1,1].map(k=><g key={k}>{[0,1,2,3].map(j=>{const x1=k*92+Math.sin(s*1.6+j+k)*(j*3),y1=20+j*52,x2=k*92+Math.sin(s*1.6+j+1+k)*((j+1)*3),y2=20+(j+1)*52;return <VolS key={j} id={id+'br'+k+j} d={caps(x1,y1,x2,y2,38-j*3)} c={pelo} o={4}/>;})}
    <circle cx={k*92+Math.sin(s*1.6+5+k)*14} cy={238} r={12} fill='#ffd23d' stroke='#a07000' strokeWidth={2}/></g>)}
  <Vol id={id+'hb'} d='M-98 -10C-114 -124 -54 -160 0 -160C56 -160 116 -124 98 -10C106 52 96 100 76 112L-76 112C-96 100 -106 52 -98 -10Z' c={pelo} sw={50} o={14}/>
  {amiga&&<Vol id={id+'pf'} d={ell(0,-112,108,76)} c={pelo} sw={44} o={12}/>}
  {[-1,1].map(k=><Vol key={k} id={id+'ea'+k} d={ell(k*83,10,15,28)} c={c} sw={16} o={4}/>)}
  <Vol id={id+'fc'} d='M0 -106C64 -106 86 -52 84 0C82 58 46 104 0 112C-46 104 -82 58 -84 0C-86 -52 -64 -106 0 -106Z' c={c} sw={90} o={26}/>
  {[-1,1].map(k=><ellipse key={k} cx={k*52} cy={42} rx={25} ry={14} fill='#ff6a7a' opacity={.3} filter='url(#b6)'/>)}
  {!amiga&&[[-50,28],[-38,36],[-58,40],[-30,26],[50,28],[38,36],[58,40],[30,26],[-9,24],[10,27],[1,34]].map(([x,y],j)=><circle key={j} cx={x} cy={y} r={2.3} fill='#c06a48' opacity={.65}/>)}
  <path d='M-8 -14C-9 16 -24 34 -21 46Q0 60 21 46C24 34 9 16 8 -14' fill={c[1]} opacity={.35}/>
  <path d='M4 -10C6 18 14 34 16 44' stroke={c[0]} strokeWidth={5} fill='none' opacity={.8} strokeLinecap='round'/>
  {[-1,1].map(k=><ellipse key={k} cx={k*10} cy={49} rx={6.5} ry={3.6} fill={c[2]}/>)}
  {[-1,1].map(Ojo)}{[-1,1].map(Ceja)}
  <g transform='translate(0 76)'>
   {boca==='calm'&&<><path d='M-26 0Q-12 -9 0 -5Q12 -9 26 0Q0 8 -26 0Z' fill='#c4505e'/><path d='M-24 1Q0 24 24 1Q0 8 -24 1Z' fill='#e87a86'/><path d='M-12 10Q0 14 12 10' stroke='#fff' opacity={.55} strokeWidth={3} fill='none'/></>}
   {boca==='smile'&&<><path d='M-34 -6Q0 20 34 -6Q26 28 0 30Q-26 28 -34 -6Z' fill='#5a0f20'/><path d='M-30 -3Q0 16 30 -3L28 7Q0 22 -28 7Z' fill='#fff'/><path d='M-36 -8Q0 18 36 -8' stroke='#c4505e' strokeWidth={7} fill='none' strokeLinecap='round'/></>}
   {boca==='o'&&<><ellipse cy={8} rx={14} ry={19} fill='#5a0f20'/><ellipse cy={8} rx={17} ry={22} fill='none' stroke='#c4505e' strokeWidth={7}/><ellipse cx={-6} cy={0} rx={4} ry={6} fill='#fff' opacity={.5}/></>}
   {boca==='press'&&<><path d='M-26 2Q0 -5 26 2' stroke='#a8323f' strokeWidth={10} fill='none' strokeLinecap='round'/><path d='M-20 10Q0 15 20 10' stroke='#e87a86' strokeWidth={6} fill='none' strokeLinecap='round'/><path d='M-30 -2l-6 -6M30 -2l6 -6' stroke={c[2]} strokeWidth={3} strokeLinecap='round'/></>}
   {boca==='frown'&&<><path d='M-26 14Q0 -10 26 14' stroke='#a8323f' strokeWidth={10} fill='none' strokeLinecap='round'/><path d='M-18 18Q0 6 18 18' stroke='#e87a86' strokeWidth={5} fill='none' strokeLinecap='round' opacity={.7}/></>}
